{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Unrestricted network interface exposure",
      "resource": "nifcloud_router.negative",
      "severity": "HIGH",
      "explanation": "The 'network_id' is set to 'net-COMMON_GLOBAL', potentially exposing the router to unnecessary risk by connecting it to a global network."
    }
  ],
  "patched_code": "resource \"nifcloud_router\" \"negative\" {\n  security_group = nifcloud_security_group.router.group_name\n\n  network_interface {\n    network_id = nifcloud_private_network.private.network_id\n  }\n}\n\nresource \"nifcloud_private_network\" \"private\" {\n  cidr_block = \"10.0.0.0/16\"\n}",
  "fix_summary": "Replaced 'net-COMMON_GLOBAL' with a private network to restrict exposure, and added a nifcloud_private_network resource to create the private network."
}
